export const meta = {
  name: 'wa-imsg-parity-audit',
  description: 'Find WhatsApp Business vs iMessage parity gaps in spectrum-ts and classify fixability',
  phases: [
    { title: 'Map', detail: 'capability matrix per provider per direction' },
    { title: 'Diff', detail: 'candidate parity gaps' },
    { title: 'Verify', detail: 'adversarial fixability check per gap' },
  ],
}

const REPO = '/Users/riceontopp/Developer/photon-ai/spectrum-ts'
const CONTENT_TYPES = ['text','markdown','attachment','voice','reply','reaction','edit','unsend','read','typing','group','contact','poll','poll_option','richlink','effect','streamText','rename','avatar','addMember','removeMember','leaveSpace','app','custom']

const CAP_SCHEMA = {
  type: 'object',
  required: ['capabilities'],
  properties: {
    capabilities: {
      type: 'array',
      items: {
        type: 'object',
        required: ['feature', 'status', 'evidence'],
        properties: {
          feature: { type: 'string', description: 'core content type or platform feature name' },
          status: { type: 'string', enum: ['full', 'partial', 'degraded-to-custom', 'dropped', 'unsupported-error', 'not-applicable'] },
          evidence: { type: 'string', description: 'file:line references and 1-2 sentence explanation' },
          dataAvailable: { type: 'boolean', description: 'does the platform SDK/API expose the data even if we drop it' },
          notes: { type: 'string' },
        },
      },
    },
  },
}

const GAPS_SCHEMA = {
  type: 'object',
  required: ['gaps'],
  properties: {
    gaps: {
      type: 'array',
      items: {
        type: 'object',
        required: ['title', 'direction', 'description', 'evidence', 'suspectedFixable'],
        properties: {
          title: { type: 'string', maxLength: 80 },
          direction: { type: 'string', enum: ['inbound', 'outbound', 'both'] },
          description: { type: 'string' },
          evidence: { type: 'string', description: 'file:line refs from the capability maps' },
          suspectedFixable: { type: 'boolean' },
          severity: { type: 'string', enum: ['high', 'medium', 'low'] },
        },
      },
    },
  },
}

const VERDICT_SCHEMA = {
  type: 'object',
  required: ['isReal', 'classification', 'reasoning'],
  properties: {
    isReal: { type: 'boolean', description: 'true if the gap actually exists in current code' },
    classification: { type: 'string', enum: ['fixable-in-repo', 'needs-sdk-or-server-change', 'platform-limitation', 'false-positive'] },
    reasoning: { type: 'string' },
    fixSketch: { type: 'string', description: 'if fixable, 2-4 sentence sketch of the fix with file refs' },
    effort: { type: 'string', enum: ['small', 'medium', 'large'] },
  },
}

const mapperPrompt = (provider, dir, extra) => `You are auditing the ${provider} provider in the spectrum-ts repo at ${REPO} for ${dir} message handling.

Read the provider source thoroughly: ${REPO}/packages/${provider}/src/ (all files${provider === 'imessage' ? ', especially remote/ and shared/ and content/' : ''}). Also consult the platform SDK typings: ${provider === 'whatsapp-business' ? `${REPO}/node_modules/@photon-ai/whatsapp-business/dist/index.d.ts (InboundMessage, MessageContext, content oneofs, client send methods)` : `${REPO}/node_modules/@photon-ai/advanced-imessage/dist (or wherever @photon-ai/advanced-imessage types live; it may be symlinked)`}.

The core Spectrum content types are: ${CONTENT_TYPES.join(', ')}. Core helpers live in ${REPO}/packages/core/src/content/.

For EACH core content type plus any platform-specific features (${extra}), determine how ${dir} handling treats it:
- 'full': faithfully mapped to/from the proper Spectrum content type
- 'partial': mapped but loses information (say what is lost)
- 'degraded-to-custom': emitted as asCustom instead of a proper type
- 'dropped': data exists in the platform payload/SDK but is silently discarded
- 'unsupported-error': explicitly throws UnsupportedError
- 'not-applicable': platform has no such concept

For every entry set dataAvailable: whether the platform SDK/API actually exposes the underlying data (check the .d.ts). Cite file:line evidence for every claim — do not guess. Read the actual switch/case mapping functions line by line (e.g. mapContent, sendContent/send* functions). Return via StructuredOutput only.`

phase('Map')
const [waIn, waOut, imIn, imOut] = await parallel([
  () => agent(mapperPrompt('whatsapp-business', 'inbound (webhook -> Spectrum message)', 'context/quoted-reply, forwarded flags, stickers, location, orders, interactive, referrals, ephemeral'), { label: 'map:wa-inbound', phase: 'Map', schema: CAP_SCHEMA }),
  () => agent(mapperPrompt('whatsapp-business', 'outbound (Spectrum content -> Cloud API send)', 'reply/quote sending, reactions, read receipts, typing, media captions, polls-via-interactive'), { label: 'map:wa-outbound', phase: 'Map', schema: CAP_SCHEMA }),
  () => agent(mapperPrompt('imessage', 'inbound (webhook -> Spectrum message)', 'tapbacks, replies/threads, edits, unsend, effects, group events, voice messages, rich links'), { label: 'map:imsg-inbound', phase: 'Map', schema: CAP_SCHEMA }),
  () => agent(mapperPrompt('imessage', 'outbound (Spectrum content -> send)', 'tapbacks, replies, edits, unsend, typing, read receipts, effects'), { label: 'map:imsg-outbound', phase: 'Map', schema: CAP_SCHEMA }),
])

const maps = { waIn, waOut, imIn, imOut }
const missing = Object.entries(maps).filter(([, v]) => !v).map(([k]) => k)
if (missing.length) { log(`WARNING: mapper(s) failed: ${missing.join(', ')} — diffing with what we have`) }

phase('Diff')
const diff = await agent(`You are comparing WhatsApp Business vs iMessage provider parity in spectrum-ts (${REPO}).

Here are four capability matrices produced by auditors who read the code (evidence includes file:line refs):

## WhatsApp Business INBOUND
${JSON.stringify(waIn?.capabilities ?? 'AUDIT FAILED', null, 1)}

## WhatsApp Business OUTBOUND
${JSON.stringify(waOut?.capabilities ?? 'AUDIT FAILED', null, 1)}

## iMessage INBOUND
${JSON.stringify(imIn?.capabilities ?? 'AUDIT FAILED', null, 1)}

## iMessage OUTBOUND
${JSON.stringify(imOut?.capabilities ?? 'AUDIT FAILED', null, 1)}

Produce the list of PARITY GAPS: places where iMessage delivers a richer/more faithful Spectrum experience than WhatsApp Business (or vice versa where WhatsApp drops data the platform provides). Prioritize:
1. Data the WhatsApp platform DOES expose (dataAvailable=true) but our mapping drops or degrades (these are fixable app bugs — like the known inbound reply-context loss).
2. Features mapped as asCustom on one platform but proper Spectrum types on the other.
3. Asymmetries between inbound and outbound on the same platform (e.g. we can SEND replies but do not surface RECEIVED replies).
Exclude gaps that are purely platform-impossible (e.g. WhatsApp has no message effects) unless partial emulation is plausible — mark those suspectedFixable=false and severity low, or omit if clearly impossible.
Merge duplicates. One already-known gap to include: inbound WhatsApp quoted-reply context dropped in mapContent. Return via StructuredOutput.`, { label: 'diff:parity', phase: 'Diff', schema: GAPS_SCHEMA })

const gaps = (diff?.gaps ?? []).slice(0, 20)
if (diff?.gaps && diff.gaps.length > 20) { log(`capped verification at 20 of ${diff.gaps.length} gaps`) }
log(`${gaps.length} candidate gaps found — verifying each`)

phase('Verify')
const verified = await parallel(gaps.map((g) => () =>
  agent(`Adversarially verify this claimed WhatsApp-Business-vs-iMessage parity gap in spectrum-ts (${REPO}). Try to REFUTE it: read the cited files and the actual current code. Maybe the code already handles it, maybe the claimed data is not actually in the SDK, maybe the evidence is misread.

CLAIM: ${g.title}
Direction: ${g.direction}
Description: ${g.description}
Evidence: ${g.evidence}

Steps:
1. Read the cited code in ${REPO}/packages/whatsapp-business/src/ and ${REPO}/packages/imessage/src/ — verify the gap exists in CURRENT code.
2. Check ${REPO}/node_modules/@photon-ai/whatsapp-business/dist/index.d.ts for whether the SDK exposes the needed data/methods (both InboundMessage shapes and client send methods).
3. Use your knowledge of the Meta WhatsApp Cloud API: does the platform itself support this (webhook fields / send endpoints)?
4. Classify: 'fixable-in-repo' (data/methods exist, just not mapped), 'needs-sdk-or-server-change' (Cloud API supports it but @photon-ai/whatsapp-business SDK does not expose it), 'platform-limitation' (WhatsApp genuinely cannot do this), or 'false-positive' (code already handles it or claim is wrong).
If fixable, sketch the fix with concrete file:line refs. Return via StructuredOutput only.`, { label: `verify:${g.title.slice(0, 40)}`, phase: 'Verify', schema: VERDICT_SCHEMA })
    .then((v) => ({ ...g, verdict: v }))
))

const results = verified.filter(Boolean).filter((g) => g.verdict && g.verdict.isReal && g.verdict.classification !== 'false-positive')
const order = { high: 0, medium: 1, low: 2 }
results.sort((a, b) => (order[a.severity] ?? 3) - (order[b.severity] ?? 3))
return {
  confirmedGaps: results,
  falsePositives: verified.filter(Boolean).filter((g) => !g.verdict || !g.verdict.isReal || g.verdict.classification === 'false-positive').map((g) => g.title),
  mapperFailures: missing,
}

